import{_ as t,o as i,c as r,a3 as o}from"./chunks/framework.DQ-7HQaQ.js";const m=JSON.parse('{"title":"Decisions and open questions","description":"","frontmatter":{},"headers":[],"relativePath":"project/decisions.md","filePath":"project/decisions.md","lastUpdated":1794433168000}'),a={name:"project/decisions.md"};function n(d,e,s,c,l,p){return i(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="decisions-and-open-questions" tabindex="-1">Decisions and open questions <a class="header-anchor" href="#decisions-and-open-questions" aria-label="Permalink to &quot;Decisions and open questions&quot;">​</a></h1><p>Planning baseline: November 10, 2026. Confirmed direction comes from the user; detailed implementation choices remain proposed until their review gates. Earlier ADRs remain reference material.</p><table tabindex="0"><thead><tr><th>ID</th><th>Decision</th><th>Status / consequence</th></tr></thead><tbody><tr><td>D-01</td><td>Current work is documentation and synthetic contract examples only</td><td>Confirmed scope; no runtime deployment or DNS changes</td></tr><tr><td>D-02</td><td>Rust owns state and coordination</td><td>Confirmed direction; use established libraries rather than rewrite codecs/databases</td></tr><tr><td>D-03</td><td>SQLite plus immutable objects form the portable library</td><td>Proposed; package, transaction and export tests required</td></tr><tr><td>D-04</td><td>Workers use language-neutral process contracts</td><td>Confirmed direction; native acceleration is optional</td></tr><tr><td>D-05</td><td>Review HTTP/JSON envelopes before choosing Protobuf</td><td>Proposed; capability semantics matter more than transport branding</td></tr><tr><td>D-06</td><td>SvelteKit/TypeScript client; Rust Axum/Tokio service</td><td>Proposed; VitePress remains documentation-only</td></tr><tr><td>D-07</td><td>Transactional local jobs/events before a broker</td><td>Proposed revision; historical Rust kernel is the extraction starting point</td></tr><tr><td>D-08</td><td>HTTPS commands and SSE for chat/progress</td><td>Proposed; explicit terminal outcomes and authorized replay</td></tr><tr><td>D-09</td><td>Local authoring publishes immutable cloud revisions</td><td>Proposed; no two-writer library synchronization in v1</td></tr><tr><td>D-10</td><td>Ambiguous identity stays unresolved</td><td>Confirmed quality direction; no name-only or vector-only merge</td></tr><tr><td>D-11</td><td><code>is373-rag</code> is the planning/build home</td><td>Working repository choice; donor repositories stay unchanged</td></tr><tr><td>D-12</td><td>Portfolio, docs and application hosting are separate</td><td>Confirmed direction; actual domain cutover is a separate operation</td></tr><tr><td>D-13</td><td>Harvest pinned historical and current Ordo behavior, not whole products</td><td>User-requested reuse direction; rights/dependency tests gate each import</td></tr><tr><td>D-14</td><td>Hosted API/workers are replaceable; a private Rust store owns durability</td><td>Proposed twelve-factor boundary; local embedded store is an explicit exception</td></tr><tr><td>D-15</td><td>Immutable release promotion, typed config and explicit model mode</td><td>Required operational direction; verify each TF gate before a compliance claim</td></tr><tr><td>D-16</td><td>Candidate identity, canonical identity and byte integrity are different</td><td>Required data invariant; replace metadata-derived content hashes and label-keyed identity policy</td></tr></tbody></table><h2 id="reconciled-alternatives" tabindex="-1">Reconciled alternatives <a class="header-anchor" href="#reconciled-alternatives" aria-label="Permalink to &quot;Reconciled alternatives&quot;">​</a></h2><p>The earlier architecture proposes NATS/JetStream. The revised first slice uses the recovered SQLite job/event kernel, after repair, rather than introducing a broker to mimic a larger deployment. A broker remains an option when measured multi-host needs justify it.</p><p>The current rebuild&#39;s JSON event store is not the selected durability adapter. Historical Rust transactions provide a better starting point. Current projection and executor types remain useful contract references even where their persistence and hashing mechanisms are replaced.</p><p>The workshop&#39;s React/Python/PostgreSQL application is a behavior/test donor, not the target stack. The historical graph is a review-lifecycle donor, not a complete canonical identity or scientific-confidence model. <a href="./../reuse/source-audit">Source-specific rationale</a>.</p><h2 id="decisions-still-required-before-implementation" tabindex="-1">Decisions still required before implementation <a class="header-anchor" href="#decisions-still-required-before-implementation" aria-label="Permalink to &quot;Decisions still required before implementation&quot;">​</a></h2><p>At S0 choose the runtime toolchain, initial corpus/media budget, authentication approach and exact wire/schema versioning policy. At S4 choose an embedding model and evaluation set; lexical baseline work need not wait for an unselected model. At S6 choose format migration/retention policy and native worker authentication/isolation. At S7 select hosting capacity and model egress policy from verified inventory and measurements.</p><p>The public application cannot depend silently on a sleeping Mac. Missing model capability is a reported state. Hardware backend substitution must preserve contract and provenance, not imply bit-identical output or compatible vectors without verification.</p><p>Domain naming, paid infrastructure and distributed execution do not block the documentation labs. Record accepted decisions with rationale, rejected alternatives, issue and evidence. Supersede prior choices explicitly; do not erase their history.</p>',11)])])}const h=t(a,[["render",n]]);export{m as __pageData,h as default};
